1	@import "tailwindcss";
2	@import "tw-animate-css";
3	@import "shadcn/tailwind.css";
4	
5	@custom-variant dark (&:is(.dark *));
6	
7	@theme inline {
8	  /* ──────────────────────────────────────────────────────────
9	     BRAND SWATCHES (single source of raw hex — Vega owns these)
10	  ────────────────────────────────────────────────────────── */
11	  --color-ink-black: #0a0a0f;
12	  --color-electric-purple: #7c3aed;
13	
14	  /* ──────────────────────────────────────────────────────────
15	     SEMANTIC PALETTE — LIGHT MODE
16	  ────────────────────────────────────────────────────────── */
17	
18	  /* Page canvas — warm off-white so cards "float" on it */
19	  --color-background: oklch(97.5% 0.003 264);
20	
21	  /* Text — near-black with a cool blue tint */
22	  --color-foreground: oklch(13% 0.015 264);
23	
24	  /* Card surface — pure white, visible against the page bg */
25	  --color-card: oklch(100% 0 0);
26	  --color-card-foreground: oklch(13% 0.015 264);
27	
28	  --color-popover: oklch(100% 0 0);
29	  --color-popover-foreground: oklch(13% 0.015 264);
30	
31	  /* Primary — same purple, unchanged */
32	  --color-primary: oklch(52% 0.24 292);
33	  --color-primary-foreground: oklch(99% 0 0);
34	
35	  /* Secondary — subtle lavender tint */
36	  --color-secondary: oklch(95.5% 0.012 292);
37	  --color-secondary-foreground: oklch(28% 0.06 292);
38	
39	  /* Muted — for backgrounds of non-interactive elements */
40	  --color-muted: oklch(95% 0.006 264);
41	  --color-muted-foreground: oklch(52% 0.02 264);
42	
43	  /* Accent — light purple for hover states and chips */
44	  --color-accent: oklch(95% 0.018 292);
45	  --color-accent-foreground: oklch(35% 0.14 292);
46	
47	  /* Destructive — unchanged */
48	  --color-destructive: oklch(59% 0.22 27);
49	  --color-destructive-foreground: oklch(99% 0 0);
50	
51	  /* ──────────────────────────────────────────────────────────
52	     SEMANTIC STATUS TOKENS
53	  ────────────────────────────────────────────────────────── */
54	  --color-success:            oklch(58% 0.18 145);
55	  --color-success-bg:         oklch(94% 0.05 145);
56	  --color-success-foreground: oklch(26% 0.12 145);
57	  --color-warning:            oklch(70% 0.16 72);
58	  --color-warning-bg:         oklch(94% 0.07 72);
59	  --color-warning-foreground: oklch(36% 0.15 72);
60	
61	  /* Borders — visible but light */
62	  --color-border: oklch(91% 0.008 264);
63	  --color-input: oklch(91% 0.008 264);
64	  --color-ring: oklch(52% 0.24 292);
65	
66	  /* ──────────────────────────────────────────────────────────
67	     SHADOWS — custom (never use Tailwind default shadow-sm/md)
68	  ────────────────────────────────────────────────────────── */
69	
70	  /* Soft border shadow for cards on white */
71	  --shadow-soft: 0 1px 2px 0 oklch(13% 0.015 264 / 0.05), 0 1px 3px 0 oklch(13% 0.015 264 / 0.04);
72	
73	  /* Standard card elevation — visible on off-white page */
74	  --shadow-card: 0 1px 3px 0 oklch(13% 0.015 264 / 0.07), 0 1px 2px -1px oklch(13% 0.015 264 / 0.05);
75	
76	  /* Hover elevation */
77	  --shadow-card-hover: 0 4px 12px -2px oklch(13% 0.015 264 / 0.10), 0 2px 6px -2px oklch(13% 0.015 264 / 0.07);
78	
79	  /* Medium depth for drawers, modals */
80	  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 264 / 0.10), 0 2px 8px -2px oklch(13% 0.015 264 / 0.07);
81	
82	  /* Floating elements — command palette, toasts, tooltips */
83	  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 264 / 0.14),
84	                 0 4px 10px -2px oklch(13% 0.015 264 / 0.08);
85	
86	  /* Full-screen overlays — modal backdrop shadow on dialog */
87	  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 264 / 0.22),
88	                    0 8px 24px -4px oklch(13% 0.015 264 / 0.12);
89	
90	  /* ──────────────────────────────────────────────────────────
91	     RADIUS
92	  ────────────────────────────────────────────────────────── */
93	  --radius: 0.5rem;
94	  --radius-sm: 0.25rem;
95	  --radius-md: 0.5rem;
96	  --radius-lg: 0.75rem;
97	  --radius-xl: 1rem;
98	  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
99	  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */
100

100	
101	  /* ──────────────────────────────────────────────────────────
102	     TYPOGRAPHY
103	  ────────────────────────────────────────────────────────── */
104	  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
105	  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;
106	
107	  /* ──────────────────────────────────────────────────────────
108	     TYPOGRAPHY SCALE — semantic names
109	  ────────────────────────────────────────────────────────── */
110	  --text-display-size:    2.25rem;  /* 36px */
111	  --text-display-height:  2.5rem;   /* 40px */
112	  --text-display-weight:  700;
113	  --text-display-track:   -0.02em;
114	
115	  --text-h1-size:    1.75rem;       /* 28px */
116	  --text-h1-height:  2rem;          /* 32px */
117	  --text-h1-weight:  700;
118	  --text-h1-track:   -0.015em;
119	
120	  --text-h2-size:    1.25rem;       /* 20px */
121	  --text-h2-height:  1.75rem;       /* 28px */
122	  --text-h2-weight:  600;
123	  --text-h2-track:   -0.01em;
124	
125	  --text-h3-size:    1rem;          /* 16px */
126	  --text-h3-height:  1.5rem;        /* 24px */
127	  --text-h3-weight:  600;
128	  --text-h3-track:   -0.005em;
129	
130	  --text-body-size:    0.875rem;    /* 14px */
131	  --text-body-height:  1.25rem;     /* 20px */
132	  --text-body-weight:  400;
133	  --text-body-track:   0em;
134	
135	  --text-body-sm-size:    0.8125rem; /* 13px */
136	  --text-body-sm-height:  1.125rem;  /* 18px */
137	  --text-body-sm-weight:  400;
138	  --text-body-sm-track:   0em;
139	
140	  --text-caption-size:    0.75rem;  /* 12px */
141	  --text-caption-height:  1rem;     /* 16px */
142	  --text-caption-weight:  400;
143	  --text-caption-track:   0em;
144	
145	  --text-micro-size:    0.625rem;   /* 10px */
146	  --text-micro-height:  0.875rem;   /* 14px */
147	  --text-micro-weight:  500;
148	  --text-micro-track:   0.06em;     /* uppercase tracking */
149	
150	  /* ──────────────────────────────────────────────────────────
151	     SPACING CONSTANTS — semantic aliases
152	  ────────────────────────────────────────────────────────── */
153	  --spacing-page-x:      1.5rem;   /* px-6 — desktop page horizontal padding */
154	  --spacing-page-x-sm:   1rem;     /* px-4 — mobile page horizontal padding */
155	  --spacing-page-y:      1.5rem;   /* py-6 — vertical section gap */
156	  --spacing-card-pad:    1.5rem;   /* p-6  — card internal padding */
157	  --spacing-card-gap:    1rem;     /* gap-4 — gap between cards in a grid */
158	  --spacing-section-gap: 1.5rem;   /* space-y-6 — between page sections */
159	  --spacing-field-gap:   1rem;     /* space-y-4 — between form fields */
160	
161	  /* ──────────────────────────────────────────────────────────
162	     ICON SIZE SCALE — reference constants (see lib/design-tokens.ts)
163	  ────────────────────────────────────────────────────────── */
164	  --icon-xs:  0.75rem;   /* 12px */
165	  --icon-sm:  0.875rem;  /* 14px */
166	  --icon-md:  1rem;      /* 16px */
167	  --icon-lg:  1.25rem;   /* 20px */
168	  --icon-xl:  1.5rem;    /* 24px */
169	  --icon-2xl: 2rem;      /* 32px */
170	
171	  /* ──────────────────────────────────────────────────────────
172	     SIDEBAR TOKENS (shadcn sidebar primitives)
173	  ────────────────────────────────────────────────────────── */
174	  --sidebar: oklch(100% 0 0);
175	  --sidebar-background: oklch(100% 0 0);
176	  --sidebar-foreground: oklch(22% 0.015 264);
177	  --sidebar-primary: oklch(52% 0.24 292);
178	  --sidebar-primary-foreground: oklch(99% 0 0);
179	  --sidebar-accent: oklch(95.5% 0.018 292);
180	  --sidebar-accent-foreground: oklch(35% 0.14 292);
181	  --sidebar-border: oklch(91% 0.008 264);
182	  --sidebar-ring: oklch(52% 0.24 292);
183	  --sidebar-width: 15rem;
184	  --sidebar-width-mobile: 18rem;
185	  --sidebar-width-icon: 3.5rem;
186	
187	  /* shadcn token aliases */
188	  --color-sidebar: var(--sidebar);
189	  --color-sidebar-foreground: var(--sidebar-foreground);
190	  --color-sidebar-primary: var(--sidebar-primary);
191	  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
192	  --color-sidebar-accent: var(--sidebar-accent);
193	  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
194	  --color-sidebar-border: var(--sidebar-border);
195	  --color-sidebar-ring: var(--sidebar-ring);
196	
197	  /* ──────────────────────────────────────────────────────────
198	     PAGE LAYOUT — light mode
199	  ────────────────────────────────────────────────────────── */
200	  --color-page-bg: oklch(97.5% 0.003 264);
201	  --color-header-bg: oklch(100% 0 0);
202	  --color-surface-1: oklch(100% 0 0);
203	  --color-surface-2: oklch(97.5% 0.003 264);
204	
205	  /* ──────────────────────────────────────────────────────────
206	     STATUS BADGES — tattoo booking lifecycle
207	  ────────────────────────────────────────────────────────── */
208	  --color-status-pending: oklch(70% 0.16 72);
209	  --color-status-confirmed: oklch(62% 0.24 292);
210	  --color-status-in-progress: oklch(60% 0.2 200);
211	  --color-status-completed: oklch(58% 0.18 145);
212	  --color-status-cancelled: oklch(55% 0.02 264);
213	  --color-status-no-show: oklch(55% 0.22 27);
214	
215	  /* ──────────────────────────────────────────────────────────
216	     NEON ACCENT
217	  ────────────────────────────────────────────────────────── */
218	  --color-neon-purple: oklch(72% 0.28 292);
219	  --color-neon-purple-glow: 0 0 20px oklch(72% 0.28 292 / 0.4);
220	
221	  /* ──────────────────────────────────────────────────────────
222	     CONSENT — submission status colors (Sprint 5)
223	  ────────────────────────────────────────────────────────── */
224	  --color-consent-signed:       oklch(58% 0.18 145);
225	  --color-consent-pending:      oklch(70% 0.16 72);
226	  --color-consent-expired:      oklch(55% 0.02 264);
227	  --color-consent-deleted:      oklch(45% 0.02 264);
228	  --color-consent-opened:       oklch(60% 0.22 230);
229	
230	  /* ──────────────────────────────────────────────────────────
231	     CONSENT — template kind badge colors
232	  ────────────────────────────────────────────────────────── */
233	  --color-kind-tattoo:   oklch(62% 0.24 292);
234	  --color-kind-piercing: oklch(60% 0.22 230);
235	  --color-kind-pmu:      oklch(60% 0.24 340);
236	  --color-kind-touchup:  oklch(70% 0.16 72);
237	  --color-kind-minor:    oklch(55% 0.22 27);
238	
239	  /* ──────────────────────────────────────────────────────────
240	     CONSENT — signature pad
241	  ────────────────────────────────────────────────────────── */
242	  --color-sig-bg:              oklch(6% 0.01 264);
243	  --color-sig-stroke:          oklch(97% 0.01 264);
244	  --color-sig-border:          oklch(28% 0.04 292);
245	  --color-sig-border-active:   oklch(62% 0.24 292 / 0.6);
246	
247	  /* ──────────────────────────────────────────────────────────
248	     CONSENT — public signing page
249	  ────────────────────────────────────────────────────────── */
250	  --color-signing-bg:              oklch(8% 0.01 264);
251	  --color-signing-card:            oklch(12% 0.02 264);
252	  --color-signing-progress-track:  oklch(20% 0.02 264);
253	  --color-signing-progress-fill:   var(--studio-brand-color, oklch(62% 0.24 292));
254	
255	  /* ──────────────────────────────────────────────────────────
256	     CONSENT — template builder
257	  ────────────────────────────────────────────────────────── */
258	  --color-builder-panel-bg:       oklch(10% 0.015 264);
259	  --color-builder-section-bg:     oklch(14% 0.02 264);
260	  --color-builder-section-hover:  oklch(17% 0.025 264);
261	  --color-builder-section-drag:   oklch(12% 0.015 264 / 0.8);
262	  --color-builder-palette-item:   oklch(16% 0.02 264);
263	
264	  /* ──────────────────────────────────────────────────────────
265	     CONSENT — REACH disclosure
266	  ────────────────────────────────────────────────────────── */
267	  --color-reach-bg:     oklch(12% 0.03 292 / 0.4);
268	  --color-reach-border: oklch(62% 0.24 292 / 0.2);
269	
270	  /* ──────────────────────────────────────────────────────────
271	     RETENTION COUNTDOWN
272	  ────────────────────────────────────────────────────────── */
273	  --color-retention-safe: oklch(55% 0.02 264);
274	  --color-retention-warn: oklch(70% 0.16 72);
275	  --color-retention-crit: oklch(55% 0.22 27);
276	
277	  /* ──────────────────────────────────────────────────────────
278	     ANIMATIONS
279	  ────────────────────────────────────────────────────────── */
280	  --animate-fade-in-up: fade-in-up 0.35s ease-out;
281	  --animate-fade-in: fade-in 0.2s ease-out;
282	  --animate-slide-in-right: slide-in-right 0.25s ease-out;
283	
284	  @keyframes fade-in-up {
285	    from { opacity: 0; transform: translateY(6px); }
286	    to   { opacity: 1; transform: translateY(0); }
287	  }
288	  @keyframes fade-in {
289	    from { opacity: 0; }
290	    to   { opacity: 1; }
291	  }
292	  @keyframes slide-in-right {
293	    from { opacity: 0; transform: translateX(8px); }
294	    to   { opacity: 1; transform: translateX(0); }
295	  }
296	
297	  /* ──────────────────────────────────────────────────────────
298	     ONBOARDING PROGRESS
299	  ────────────────────────────────────────────────────────── */

645	  --color-surface-1: oklch(14.5% 0.014 264);
646	  --color-surface-2: oklch(17% 0.016 264);
647	  --shadow-soft:    0 1px 2px 0 oklch(0% 0 0 / 0.25), 0 1px 3px 0 oklch(0% 0 0 / 0.18);
648	  --shadow-soft-md: 0 4px 16px -4px oklch(0% 0 0 / 0.35), 0 2px 8px -2px oklch(0% 0 0 / 0.22);
649	  --shadow-lift:    0 8px 24px -4px oklch(0% 0 0 / 0.50), 0 4px 10px -2px oklch(0% 0 0 / 0.30);
650	  --shadow-overlay: 0 24px 64px -12px oklch(0% 0 0 / 0.65), 0 8px 24px -4px oklch(0% 0 0 / 0.40);
651	  --shadow-card: 0 1px 3px 0 oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.2);
652	  --shadow-card-hover: 0 4px 12px -2px oklch(0% 0 0 / 0.4), 0 2px 6px -2px oklch(0% 0 0 / 0.3);
653	  /* ── Status tokens dark mode ── */
654	  --color-success:            oklch(62% 0.18 145);
655	  --color-success-bg:         oklch(20% 0.06 145);
656	  --color-success-foreground: oklch(82% 0.12 145);
657	  --color-warning:            oklch(72% 0.16 72);
658	  --color-warning-bg:         oklch(22% 0.07 72);
659	  --color-warning-foreground: oklch(86% 0.12 72);
660	  --sidebar: oklch(14.5% 0.014 264);
661	  --sidebar-background: oklch(14.5% 0.014 264);
662	  --sidebar-foreground: oklch(85% 0.01 264);
663	  --sidebar-primary: oklch(65% 0.24 292);
664	  --sidebar-primary-foreground: oklch(10% 0.01 292);
665	  --sidebar-accent: oklch(20% 0.04 292);
666	  --sidebar-accent-foreground: oklch(80% 0.06 292);
667	  --sidebar-border: oklch(22% 0.015 264);
668	}
669	
670	@layer base {
671	  *,
672	  *::before,
673	  *::after {
674	    border-color: var(--color-border);
675	    outline-color: var(--color-ring);
676	  }
677	
678	  html {
679	    -webkit-font-smoothing: antialiased;
680	    -moz-osx-font-smoothing: grayscale;
681	    text-rendering: optimizeLegibility;
682	  }
683	
684	  body {
685	    background-color: var(--color-background);
686	    color: var(--color-foreground);
687	    font-family: var(--font-sans);
688	  }
689	
690	  h1 {
691	    font-size: var(--text-h1-size);
692	    line-height: var(--text-h1-height);
693	    font-weight: var(--text-h1-weight);
694	    letter-spacing: var(--text-h1-track);
695	  }
696	
697	  h2 {
698	    font-size: var(--text-h2-size);
699	    line-height: var(--text-h2-height);
700	    font-weight: var(--text-h2-weight);
701	    letter-spacing: var(--text-h2-track);
702	  }
703	
704	  h3 {
705	    font-size: var(--text-h3-size);
706	    line-height: var(--text-h3-height);
707	    font-weight: var(--text-h3-weight);
708	    letter-spacing: var(--text-h3-track);
709	  }
710	
711	  /* Global Lucide icon stroke weight — 1.5px matches Linear/Vercel Geist */
712	  svg.lucide {
713	    stroke-width: 1.5;
714	  }
715	
716	  .tabular { font-variant-numeric: tabular-nums; }
717	
718	  /* Global interaction transitions */
719	  button, [role="button"], a, [data-slot="button"] {
720	    transition-property: color, background-color, border-color, box-shadow, transform;
721	    transition-duration: 150ms;
722	    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
723	  }
724	}
725	
726	@layer utilities {
727	  /* Card hover utility */
728	  .card-interactive {
729	    transition: box-shadow 200ms ease, border-color 200ms ease, transform 200ms ease;
730	  }
731	  .card-interactive:hover {
732	    box-shadow: var(--shadow-soft-md);
733	    border-color: oklch(52% 0.24 292 / 0.2);
734	  }
735	
736	  /* Stagger animation helper */
737	  .stagger-fade-in > * {
738	    opacity: 0;
739	    animation: fade-in-up 0.4s ease forwards;
740	  }
741	  .stagger-fade-in > *:nth-child(1) { animation-delay: 0ms; }
742	  .stagger-fade-in > *:nth-child(2) { animation-delay: 50ms; }
743	  .stagger-fade-in > *:nth-child(3) { animation-delay: 100ms; }
744	  .stagger-fade-in > *:nth-child(4) { animation-delay: 150ms; }

745	  .stagger-fade-in > *:nth-child(5) { animation-delay: 200ms; }
746	  .stagger-fade-in > *:nth-child(6) { animation-delay: 250ms; }
747	
748	  /* Stagger children — 40ms steps */
749	  .stagger-children > * {
750	    opacity: 0;
751	    animation: fade-in-up 0.35s ease-out forwards;
752	  }
753	  .stagger-children > *:nth-child(1)  { animation-delay: 0ms; }
754	  .stagger-children > *:nth-child(2)  { animation-delay: 40ms; }
755	  .stagger-children > *:nth-child(3)  { animation-delay: 80ms; }
756	  .stagger-children > *:nth-child(4)  { animation-delay: 120ms; }
757	  .stagger-children > *:nth-child(5)  { animation-delay: 160ms; }
758	  .stagger-children > *:nth-child(6)  { animation-delay: 200ms; }
759	  .stagger-children > *:nth-child(7)  { animation-delay: 240ms; }
760	  .stagger-children > *:nth-child(8)  { animation-delay: 280ms; }
761	
762	  /* Bulk action bar */
763	  .bulk-action-bar {
764	    position: fixed;
765	    bottom: 24px;
766	    left: 50%;
767	    transform: translateX(-50%);
768	    background: var(--color-surface-elevated, var(--color-card));
769	    border: 1px solid var(--color-border);
770	    border-radius: 0.75rem;
771	    padding: 0.75rem 1rem;
772	    box-shadow: 0 8px 32px oklch(0% 0 0 / 0.5), 0 0 0 1px oklch(22% 0.03 272);
773	    backdrop-filter: blur(12px);
774	  }
775	}
776	
777	@keyframes shimmer {
778	  0%   { background-position: -200% 0; }
779	  100% { background-position: 200% 0; }
780	}
781	
782	/* ──────────────────────────────────────────────────────────
783	   DARK MODE OVERRIDES (separate palette — NOT inverted)
784	────────────────────────────────────────────────────────── */
785	.dark {
786	  /* Modern dark theme — NOT pitch black. Think Linear/Notion dark mode.
787	     Background ~15%, cards ~20%, elevated ~25%. Warm slate hue (264). */
788	  --color-background: oklch(15% 0.01 264);
789	  --color-foreground: oklch(95% 0.005 264);
790	  --color-card: oklch(20% 0.015 264);
791	  --color-card-foreground: oklch(95% 0.005 264);
792	  --color-popover: oklch(20% 0.015 264);
793	  --color-popover-foreground: oklch(95% 0.005 264);
794	
795	  --color-primary: oklch(65% 0.24 292);
796	  --color-primary-foreground: oklch(99% 0 0);
797	
798	  --color-secondary: oklch(24% 0.015 264);
799	  --color-secondary-foreground: oklch(88% 0.01 264);
800	
801	  --color-muted: oklch(22% 0.01 264);
802	  --color-muted-foreground: oklch(65% 0.015 264);
803	
804	  --color-accent: oklch(25% 0.035 292);

