export const duration = {
  instant: 80,
  fast:    120,
  base:    180,
  slow:    260,
  page:    320,
} as const

export const easing = {
  standard:   'cubic-bezier(0.22, 1, 0.36, 1)',
  emphasized: 'cubic-bezier(0.32, 0.72, 0, 1)',
  linear:     'linear',
} as const

export const skeleton = {
  duration:  1600,
