export type Duration = keyof typeof duration
export type Easing = keyof typeof easing

'use client'

import { useEffect, useState } from 'react'

/**
 * Returns true when the user has requested reduced motion
 * via `prefers-reduced-motion: reduce`. SSR-safe (returns false on server).
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    setReduced(mq.matches)

    const handler = (e: MediaQueryListEvent) => { setReduced(e.matches) }
    mq.addEventListener('change', handler)
    return () => { mq.removeEventListener('change', handler) }
  }, [])

  return reduced
}

import { useRef, useEffect } from 'react'

/**
 * Returns the value from the previous render.
 * On the first render, returns `undefined`.
 */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined)
  useEffect(() => {
    ref.current = value
  })
  return ref.current
}

import { cn } from '@/lib/utils'

type FadeDuration = 'instant' | 'fast' | 'base' | 'slow'

interface FadeProps {
  in?: boolean
  children: React.ReactNode
  duration?: FadeDuration
  delay?: number
  className?: string
}

const durationVarMap: Record<FadeDuration, string> = {
  instant: 'var(--duration-instant)',
  fast:    'var(--duration-fast)',
  base:    'var(--duration-base)',
  slow:    'var(--duration-slow)',
}

/**
 * CSS-only opacity fade. Mounts always — uses opacity-0 + pointer-events-none
 * when `in=false` to avoid layout shift. Respects prefers-reduced-motion via
 * the global @media rule (transition collapses to 0.01ms automatically).
 */
export function Fade({
  in: visible = true,
  children,
  duration = 'base',
  delay,
  className,
}: FadeProps) {
  return (
    <div
      className={cn(
        'motion-safe-fade',
        'transition-opacity',
        visible ? 'opacity-100' : 'opacity-0 pointer-events-none',
        className,
      )}
      style={{
        transitionDuration: durationVarMap[duration],
        transitionTimingFunction: 'var(--ease-standard)',
        ...(delay !== undefined ? { transitionDelay: `${delay}ms` } : {}),
      }}
    >
      {children}
    </div>
  )
}

import { cn } from '@/lib/utils'

type SlideFrom = 'bottom' | 'top' | 'left' | 'right'

interface SlideProps {
  in?: boolean
  from?: SlideFrom
  distance?: number
  children: React.ReactNode
  className?: string
}

function translateClass(from: SlideFrom, distance: number, visible: boolean): string {
  if (visible) return 'motion-safe:translate-x-0 motion-safe:translate-y-0'
  const px = `${distance}px`
  switch (from) {
    case 'bottom': return `motion-safe:translate-y-[${px}]`
    case 'top':    return `motion-safe:-translate-y-[${px}]`
    case 'right':  return `motion-safe:translate-x-[${px}]`
    case 'left':   return `motion-safe:-translate-x-[${px}]`
  }
}

/**
 * CSS transform + opacity slide. Transforms are gated with motion-safe: prefix
 * so reduced-motion users only get the opacity fade.
 */
export function Slide({
  in: visible = true,
  from = 'bottom',
  distance = 8,
  children,
  className,
}: SlideProps) {
  return (
    <div
      className={cn(
        'motion-safe-fade transition-[opacity,transform]',
        visible ? 'opacity-100' : 'opacity-0',
        translateClass(from, distance, visible),
        className,
      )}
      style={{
        transitionDuration: 'var(--duration-base)',
        transitionTimingFunction: 'var(--ease-standard)',
      }}
    >
      {children}
    </div>
  )
}

import React from 'react'
import { cn } from '@/lib/utils'

interface StaggerProps {
  delay?: number
  children: React.ReactNode
  className?: string
}

/**
 * Delay distributor — injects staggered animationDelay / transitionDelay
 * into each direct child via React.cloneElement. Children must supply
 * their own entrance animation (e.g. wrapped in <Fade> or <Slide>).
 * This component adds NO animation itself — pure delay distribution.
 */
export function Stagger({ delay = 40, children, className }: StaggerProps) {
  return (
    <div className={cn(className)}>
      {React.Children.map(children, (child, index) => {
        if (!React.isValidElement(child)) return child

        const existingStyle =
          (child.props as { style?: React.CSSProperties }).style ?? {}

        return React.cloneElement(child, {
          style: {
            ...existingStyle,
            animationDelay: `${delay * index}ms`,
            transitionDelay: `${delay * index}ms`,
          },
        } as React.HTMLAttributes<HTMLElement>)
      })}
    </div>
  )
}

import { cn } from '@/lib/utils'

interface PopInProps {
  in?: boolean
  children: React.ReactNode
  className?: string
}

/**
 * Scale 0.95 → 1 + opacity 0 → 1. Use for: toasts, tooltips, badge add,
 * empty state icons. Scale is gated with motion-safe: prefix.
 */
export function PopIn({ in: visible = true, children, className }: PopInProps) {
  return (
    <div
      className={cn(
        'motion-safe-fade transition-[opacity,transform]',
        visible
          ? 'opacity-100 motion-safe:scale-100'
          : 'opacity-0 motion-safe:scale-95',
        className,
      )}
      style={{
        transitionDuration: 'var(--duration-fast)',
        transitionTimingFunction: 'var(--ease-standard)',
      }}
    >
      {children}
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'

interface CountUpProps {
  from?: number
  to: number
  duration?: number
  formatter?: (n: number) => string
  className?: string
}

/** Cubic in-out easing for smooth countup */
function easeInOut(t: number): number {
  return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t
}

/**
 * Animates a number from `from` to `to` using requestAnimationFrame.
 * Respects prefers-reduced-motion: jumps directly to `to` when reduced.
 */
export function CountUp({
  from = 0,
  to,
  duration = 800,
  formatter,
  className,
}: CountUpProps) {
  const [displayed, setDisplayed] = useState<number>(from)
  const rafRef = useRef<number | null>(null)
  const startRef = useRef<number | null>(null)

  useEffect(() => {
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    if (reduced) {
      setDisplayed(to)
      return
    }

    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current)
    }
    startRef.current = null

    const animate = (timestamp: number) => {
      if (startRef.current === null) {
        startRef.current = timestamp
      }
      const elapsed = timestamp - startRef.current
      const progress = Math.min(elapsed / duration, 1)
      const eased = easeInOut(progress)
      setDisplayed(from + (to - from) * eased)

      if (progress < 1) {
        rafRef.current = requestAnimationFrame(animate)
      }
    }

    rafRef.current = requestAnimationFrame(animate)

    return () => {
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current)
      }
    }
  }, [from, to, duration])

  const formatted = formatter
    ? formatter(displayed)
    : String(Math.round(displayed))

  return <span className={cn('tabular-nums', className)}>{formatted}</span>
}

