import { useRef, useState, useEffect } from 'react'
import { Loader2 } from 'lucide-react'
import { Button as ButtonPrimitive } from '@base-ui/react/button'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:scale-[0.97] active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80 hover:shadow-[0_0_16px_oklch(62%_0.24_292_/_0.15)]",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  nativeButton,
  render,
  loading,
  loadingLabel,
  children,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof buttonVariants> & {
    loading?: boolean
    loadingLabel?: string
  }) {
  const ref = useRef<HTMLButtonElement>(null)
  const [minWidth, setMinWidth] = useState<number | undefined>(undefined)

  useEffect(() => {
    if (ref.current && minWidth === undefined) {
      setMinWidth(ref.current.offsetWidth)
    }
  }, [minWidth])

  const isNativeButton = nativeButton ?? (render == null)
  const isLoading = loading === true

  return (
    <ButtonPrimitive
      ref={ref}
      data-slot="button"
      className={cn(
        buttonVariants({ variant, size, className }),
        isLoading && 'pointer-events-none',
      )}
      nativeButton={isNativeButton}
      {...(render !== undefined ? { render } : {})}
      aria-disabled={isLoading || undefined}
      style={minWidth !== undefined ? { minWidth } : undefined}
      {...props}
    >
      <span className={cn('inline-flex items-center gap-1.5', isLoading && 'opacity-70')}>
        {isLoading && (
          <Loader2
            className="size-3.5 shrink-0 animate-spin [animation-duration:800ms]"
            aria-hidden="true"
          />
        )}
        {isLoading && loadingLabel !== undefined ? loadingLabel : children}
      </span>
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }

'use client'

import type { LucideIcon } from 'lucide-react'
import { TrendingUp, TrendingDown, AlertCircle } from 'lucide-react'
import Link from 'next/link'
import { cn } from '@/lib/utils'
import { Skeleton } from '@/components/ui/skeleton'
import { Sparkline } from '@/components/ui/sparkline'
import { CountUp } from '@/components/motion/CountUp'
import { usePrevious } from '@/lib/hooks/use-previous'

type HoverVariant = 'lift' | 'tint' | 'none'

interface KpiCardProps {
  label: string
  value: string | number
  /** Formatted delta string e.g. "+12.4%" or "-3.1%" */
  delta?: string
  /** Direction of delta — controls badge color */
  trend?: 'up' | 'down' | 'neutral'
  /** When true, "down" is good (e.g. churn rate) */
  invertTrend?: boolean
  /** Supporting text shown below delta (e.g. "vs last month") */
  subtextLabel?: string
  /** Sparkline data — array of numbers (last N periods) */
  sparkline?: number[]
  icon?: LucideIcon
  /** Card-level accent color — use a CSS token reference, not raw hex */
  accentVar?: string
  href?: string
  loading?: boolean
  error?: boolean
  /** Stagger animation delay in ms */
  index?: number
  /** Hover interaction archetype */
  hoverVariant?: HoverVariant
  /** Formatter for numeric value — passed to CountUp */
  formatter?: (n: number) => string
}

const hoverVariantClass: Record<HoverVariant, string> = {
  lift: 'hover-lift',
  tint: 'hover-tint',
  none: '',
}

function TrendBadge({
  delta,
  trend,
  invertTrend,
  subtextLabel,
}: {
  delta: string
  trend: 'up' | 'down' | 'neutral'
  invertTrend: boolean
  subtextLabel?: string
}) {
  const isPositive = invertTrend ? trend === 'down' : trend === 'up'
  const isNeutral = trend === 'neutral'

  if (isNeutral) {
    return (
      <div className="mt-2.5 flex items-center gap-1.5">
        <span className="text-[11px] text-muted-foreground">{delta}</span>
        {subtextLabel && <span className="text-[11px] text-muted-foreground">{subtextLabel}</span>}
      </div>
    )
  }

  return (
    <div className="mt-2.5 flex items-center gap-1.5">
      <span
        className={cn(
          'inline-flex items-center gap-0.5 rounded-full px-1.5 py-0.5 text-[11px] font-semibold',
          isPositive
            ? 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]'
            : 'bg-destructive/10 text-destructive',
        )}
      >
        {isPositive ? (
          <TrendingUp className="h-3 w-3" aria-hidden="true" />
        ) : (
          <TrendingDown className="h-3 w-3" aria-hidden="true" />
        )}
        {delta}
      </span>
      {subtextLabel && (
        <span className="text-[11px] text-muted-foreground">{subtextLabel}</span>
      )}
    </div>
  )
}

export function KpiCard({
  label,
  value,
  delta,
  trend = 'neutral',
  invertTrend = false,
  subtextLabel,
  sparkline,
  icon: Icon,
  accentVar = 'var(--color-primary)',
  href,
  loading = false,
  error = false,
  index = 0,
  hoverVariant = 'lift',
  formatter,
}: KpiCardProps) {
  const numericValue = typeof value === 'number' ? value : undefined
  const previousValue = usePrevious(numericValue)

  const sparklineColor =
    trend === 'up' ? 'var(--color-success)' :
    trend === 'down' ? 'var(--color-destructive)' :
    accentVar

  const cardContent = (
    <div
      className={cn(
        'group relative overflow-hidden rounded-xl bg-card',
        'border border-border',
        'shadow-[var(--shadow-card)]',
        'animate-fade-in-up p-5',
        hoverVariantClass[hoverVariant],
        href && 'cursor-pointer',
      )}
      style={{
        animationDelay: `${index * 60}ms`,
        animationFillMode: 'both',
        ['--kpi-accent' as string]: accentVar,
      }}
    >
      {/* Left accent bar */}
      <div
        className="absolute inset-y-0 left-0 w-[3px] rounded-l-xl"
        style={{ background: 'var(--kpi-accent)' }}
        aria-hidden="true"
      />

      {/* Label + icon row */}
      <div className="mb-3 flex items-center justify-between">
        <span className="text-[10px] font-medium uppercase tracking-[0.06em] text-muted-foreground">
          {label}
        </span>
        {Icon && (
          <div
            className="flex h-8 w-8 items-center justify-center rounded-lg"
            style={{ background: 'color-mix(in oklch, var(--kpi-accent) 12%, transparent)' }}
          >
            <Icon
              className="h-4 w-4"
              style={{ color: 'var(--kpi-accent)' }}
              aria-hidden="true"
            />
          </div>
        )}
      </div>

      {/* Value */}
      {loading ? (
        <Skeleton className="h-8 w-24 mt-1" />
      ) : error ? (
        <div className="flex items-center gap-1.5 mt-1">
          <AlertCircle className="size-4 text-destructive" aria-hidden="true" />
          <span className="text-xs text-destructive">Failed to load</span>
        </div>
      ) : numericValue !== undefined ? (
        <CountUp
          from={previousValue ?? 0}
          to={numericValue}
          duration={800}
          {...(formatter !== undefined ? { formatter } : {})}
          className="text-[2rem] font-bold tabular-nums leading-none tracking-tight text-foreground"
        />
      ) : (
        <div className="text-[2rem] font-bold tabular-nums leading-none tracking-tight text-foreground">
          {value}
        </div>
      )}

      {/* Sparkline */}
      {sparkline && sparkline.length > 0 && (
        loading ? (
          <Skeleton className="h-12 w-full mt-2" />
        ) : (
          <div className="mt-2">
            <Sparkline
              data={sparkline}
              height={48}
              strokeColor={sparklineColor}
              fillColor={sparklineColor}
            />
          </div>
        )
      )}

      {/* Delta / trend */}
      {delta && !loading && !error && (
        <TrendBadge
          delta={delta}
          trend={trend}
          invertTrend={invertTrend}
          {...(subtextLabel !== undefined ? { subtextLabel } : {})}
        />
      )}
      {loading && !error && (
        <Skeleton className="h-4 w-16 mt-2.5" />
      )}
    </div>
  )

  if (href) {
    return <Link href={href}>{cardContent}</Link>
  }

  return cardContent
}

import type { LucideIcon } from 'lucide-react'
import { TrendingUp, TrendingDown } from 'lucide-react'
import { cn } from '@/lib/utils'

type HoverVariant = 'lift' | 'tint' | 'none'

interface StatCardProps {
  label: string
  value: string | number
  delta?: string
  trend?: 'up' | 'down' | 'neutral'
  icon?: LucideIcon
  className?: string
  hoverVariant?: HoverVariant
}

const hoverVariantClass: Record<HoverVariant, string> = {
  lift: 'hover-lift',
