  none: '',
}

export function StatCard({
  label,
  value,
  delta,
  trend = 'neutral',
  icon: Icon,
  className,
  hoverVariant = 'lift',
}: StatCardProps) {
  const isPositive = trend === 'up'
  const isNegative = trend === 'down'

  return (
    <div
      className={cn(
        'rounded-lg border border-border bg-card p-4 shadow-[var(--shadow-soft)]',
        hoverVariantClass[hoverVariant],
        className,
      )}
    >
      {/* Top row: icon + label */}
      <div className="flex items-center gap-2 text-muted-foreground mb-1.5">
