              isPositive && 'text-[var(--color-success)]',
              isNegative && 'text-destructive',
              !isPositive && !isNegative && 'text-muted-foreground',
            )}
          >
            {isPositive && <TrendingUp className="size-3" aria-hidden="true" />}
