'use client'

import { useOptimistic, useTransition } from 'react'
import { toast } from 'sonner'

interface Item {
  id: string
  [key: string]: unknown
}

export function useOptimisticDelete<T extends Item>(
  items: T[],
  deleteAction: (id: string) => Promise<void>,
  undoAction: (item: T) => Promise<void>,
) {
  const [optimisticItems, removeOptimistically] = useOptimistic(
    items,
    (current: T[], removedId: string) => current.filter(i => i.id !== removedId),
  )
  const [isPending, startTransition] = useTransition()

  function handleDelete(item: T) {
    const deletedItem = item

    startTransition(async () => {
      removeOptimistically(item.id)

      let undone = false

      const toastId = toast('Deleted', {
        duration: 5000,
        action: {
          label: 'Undo',
          onClick: () => {
            undone = true
            void undoAction(deletedItem)
            toast.dismiss(toastId)
          },
        },
      })

      try {
        await deleteAction(item.id)
        if (!undone) toast.dismiss(toastId)
      } catch {
        toast.error("Couldn't delete · Retry", {
          action: { label: 'Retry', onClick: () => handleDelete(item) },
        })
        // useOptimistic rolls back automatically on error
      }
    })
  }

  return { optimisticItems, handleDelete, isPending }
}

'use client'

import { useOptimistic, useTransition } from 'react'
import { toast } from 'sonner'

export function useOptimisticToggle<T extends { id: string }>(
  items: T[],
  field: keyof T,
  toggleAction: (id: string, value: boolean) => Promise<void>,
) {
  const [optimisticItems, setOptimistic] = useOptimistic(
    items,
    (current: T[], update: { id: string; value: boolean }) =>
      current.map(i =>
        i.id === update.id ? { ...i, [field]: update.value } : i
      ),
  )
  const [, startTransition] = useTransition()

  function handleToggle(item: T) {
    const newValue = !item[field] as boolean

    startTransition(async () => {
      setOptimistic({ id: item.id, value: newValue })
      try {
        await toggleAction(item.id, newValue)
      } catch {
        // useOptimistic rolls back — show inline error
        toast.error('Change failed', { duration: 3000 })
      }
    })
  }

  return { optimisticItems, handleToggle }
}

'use client'

import { useOptimistic, useTransition } from 'react'
import { toast } from 'sonner'

export function useOptimisticReorder<T extends { id: string }>(
  items: T[],
  reorderAction: (orderedIds: string[]) => Promise<void>,
) {
  const [optimisticItems, reorderOptimistically] = useOptimistic(
    items,
    (_current: T[], reordered: T[]) => reordered,
  )
  const [, startTransition] = useTransition()

  function handleReorder(reordered: T[], containerRef?: React.RefObject<HTMLElement | null>) {
    startTransition(async () => {
      reorderOptimistically(reordered)
      try {
        await reorderAction(reordered.map(i => i.id))
      } catch {
        // useOptimistic auto-restores original order
        // Add red-pulse on container element if ref provided
        if (containerRef?.current) {
          containerRef.current.setAttribute('data-reorder-error', 'true')
          setTimeout(() => {
            containerRef.current?.removeAttribute('data-reorder-error')
          }, 600)
        }
        toast.error("Couldn't reorder · Retry")
      }
    })
  }

  return { optimisticItems, handleReorder }
}

import { toast } from 'sonner'

interface ToastUndoOptions<T> {
  label?: string
  undoLabel?: string
  ttl?: number
  onUndo: () => void | Promise<void>
  onExpire?: () => void
}

export function toastWithUndo<T>(options: ToastUndoOptions<T>): string | number {
  const {
    label = 'Deleted',
    undoLabel = 'Undo',
    ttl = 5000,
    onUndo,
    onExpire,
  } = options

  const id = toast(label, {
    duration: ttl,
    action: {
      label: undoLabel,
      onClick: () => {
        void onUndo()
        toast.dismiss(id)
      },
    },
    onDismiss: () => {
      onExpire?.()
    },
  })

  return id
}

