import { useRef, useEffect } from 'react'

/**
 * Returns the value from the previous render.
 * On the first render, returns `undefined`.
 * Uses a ref internally but only reads it after effects run.
 */
export function usePrevious<T>(value: T): T | undefined {
  const prevRef = useRef<T | undefined>(undefined)
  const currentRef = useRef<T>(value)

  useEffect(() => {
    prevRef.current = currentRef.current
    currentRef.current = value
  })

  return prevRef.current
}

import { useState, useEffect } from 'react'

/**
 * Returns the value from the previous render.
 * On the first render, returns `undefined`.
 */
export function usePrevious<T>(value: T): T | undefined {
  const [prev, setPrev] = useState<T | undefined>(undefined)
  const [current, setCurrent] = useState<T>(value)

  if (value !== current) {
    setPrev(current)
    setCurrent(value)
  }

  // Suppress unused effect warning — useState handles sync
  useEffect(() => {
    // intentionally empty — state updates handled inline above
  }, [])

  return prev
}
